"""One-line summary of the catalogue."""
import json

from shelf import books


def summary():
    return "%d books" % len(books.all_books())


def by_author():
    counts = {}
    for b in books.all_books():
        counts[b["author"]] = counts.get(b["author"], 0) + 1
    return counts


def as_json():
    return json.dumps({"summary": summary(), "by_author": by_author()})
EOF
cat > tests/test_report.py <<'EOF'
import json

from shelf import books, report


def setup_function():
    books.clear()


def test_by_author_counts():
    books.add("Dune", "Frank Herbert")
    books.add("Dune Messiah", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    assert report.by_author() == {"Frank Herbert": 2, "Jane Austen": 1}


def test_as_json():
    books.add("Dune", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    assert json.loads(report.as_json()) == {
        "summary": "2 books",
        "by_author": {"Frank Herbert": 1, "Jane Austen": 1},
    }


def test_as_json_empty():
    assert json.loads(report.as_json()) == {"summary": "0 books", "by_author": {}}
EOF
